import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long L = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] cells = new long[(int) q];
        for (int i = 0; i < cells.length; i++) cells[i] = Long.parseLong(next());

        int[] length = new int[(int) L + 2];
        long blocks = 0, longest = 0;
        StringBuilder blocksOut = new StringBuilder();
        StringBuilder longestOut = new StringBuilder();
        for (int t = 0; t < q; t++) {
            int x = (int) cells[t];
            if (length[x] == 0) {
                int left = length[x - 1], right = length[x + 1];
                int total = left + right + 1;
                length[x - left] = total;
                length[x + right] = total;
                length[x] = total;
                blocks += 1 - (left > 0 ? 1 : 0) - (right > 0 ? 1 : 0);
                longest = Math.max(longest, total);
            }
            if (t > 0) {
                blocksOut.append(" ");
                longestOut.append(" ");
            }
            blocksOut.append(blocks);
            longestOut.append(longest);
        }
        System.out.println(blocksOut);
        System.out.println(longestOut);
    }
}
